            pathData = PathParser().parsePathString(data).toNodes(),
            fill = SolidColor(Color.Black)
        )
    }.build()

    private fun icon24(data: String): ImageVector = ImageVector.Builder(
        defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f
    ).apply { addPath(pathData = PathParser().parsePathString(data).toNodes(), fill = SolidColor(Color.Black)) }.build()
}
